def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False).astype(float)
    df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = np.nan
    df.loc[(df['flipper_length_mm'] < 170) | (df['flipper_length_mm'] > 235), 'flipper_length_mm'] = np.nan
    df['sex'] = df['sex'].str.lower()
    return df

def answer(df):
    df = df.dropna(subset=['sex'])
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
